import type { DataSourceId } from '../bridge/types';
import { STORE_MARKS, type BrandMark } from './storeMarks';

/**
 * Track R: marks for services that aren't stores — data sources, local AI, hardware vendors and
 * cloud play — drawn on the same 24×24 grid as store marks and shown by `ServiceLogo`.
 *
 * Brand drawings are Simple Icons 16.34.0 (CC0-1.0; slugs listed in THIRD-PARTY-NOTICES.md), copied
 * here rather than bundling the package. Xbox Cloud Gaming reuses the store's Xbox sphere (Bootstrap
 * Icons, MIT). The marks are trademarks of their owners, used only to say where data comes from or
 * what it runs on. Services without a properly licensed mark get a plain, descriptive icon instead —
 * never an invented or imitated logo.
 */
export type GenericIcon = 'artwork' | 'database' | 'price' | 'deal' | 'shield' | 'pulse' | 'gift';

export type ServiceMark =
  | (BrandMark & { name: string; /** Brand hue, tuned (like the store tokens) to read on dark surfaces. */ hue: string })
  | { kind: 'generic'; name: string; icon: GenericIcon; /** Why there is no brand mark, for the record. */ reason: string };

export type ServiceId =
  | 'steamdeck'
  | 'igdb'
  | 'twitch'
  | 'wikidata'
  | 'ollama'
  | 'nvidia'
  | 'amd'
  | 'intel'
  | 'geforce-now'
  | 'xbox-cloud'
