/**
 * The maker of a graphics card or processor, from the name Windows reports ("NVIDIA GeForce RTX
 * 4060", "AMD Radeon RX 7800 XT", "Intel(R) Arc(TM) A770"). Null when the name doesn't say — the
 * mark is only shown when the device is known.
 */
export function hardwareVendor(name: string | null | undefined): 'nvidia' | 'amd' | 'intel' | null {
  if (!name) return null;
  const n = name.toLowerCase();
  if (/\bnvidia\b|\bgeforce\b|\bquadro\b|\brtx\b|\bgtx\b/.test(n)) return 'nvidia';
  if (/\bamd\b|\bradeon\b|\bryzen\b|\bati\b/.test(n)) return 'amd';
  if (/\bintel\b|\barc\b|\biris\b|\buhd graphics\b|\bcore\b.*\bi[3579]\b/.test(n)) return 'intel';
  return null;
}
